// der_keys_test.dart
//
// Test suite for der_keys.dart using package:test.
//
// Setup (once per project):
//   dart pub add --dev test
//
// Run:
//   dart test
//   dart test -r expanded          # verbose per-test output
//   dart test der_keys_test.dart   # just this file
//
// Vectors marked "OpenSSL vector" were generated by Python's `cryptography`
// library (which wraps OpenSSL), so encode() output is checked against a
// trusted third-party DER encoder, not just round-tripped against itself.
// The RFC 8032 vector is the standard Ed25519 Test 1 vector.

