// ============================================================
// BLS12-381 (Internet Computer G2 public keys)
//
// BLS12-381 has no IETF/IANA-registered DER standard, and OpenSSL has no
// BLS12-381 support at all — so unlike the other groups above, these
// vectors are NOT generated/cross-checked via OpenSSL. Instead:
//
//   - The DER wrapper (algorithm + curve OID, SPKI shape) is verified
//     against @dfinity/agent's actual source
//     (packages/core/src/agent/der.ts `BLS12_381_G2_OID`,
//      packages/core/src/agent/certificate.ts `DER_PREFIX`).
//   - realSubnetKeyVector below is a genuine subnet public key taken
//     directly from a real, signed IC certificate embedded in
//     @dfinity/agent's own test suite (certificate.test.ts), not a
//     synthetic value — its DER bytes decode cleanly under
//     `openssl asn1parse` into the expected
//     SEQUENCE{ SEQUENCE{ OID id-ic-bls12-381, OID curve }, BIT STRING(96B) }.
//   - There is no DER/PKCS8 standard anywhere for BLS12-381 *private*
//     keys; encodeBls12381PrivateKeyPkcs8 is our own construction (see
//     the comment on it in codec.dart) and is only round-tripped against
//     itself below, not against any external tool.
// ============================================================

class Bls12381PublicKeyVector {
  final String point; // raw G2 point (hex)
  final String spkiDer;
  const Bls12381PublicKeyVector({required this.point, required this.spkiDer});
}

// A real subnet public key + its real DER wrapper, taken from a genuine
// signed IC certificate in @dfinity/agent's own test fixtures
// (packages/core/src/agent/certificate.test.ts).
const realSubnetKeyVector = Bls12381PublicKeyVector(
  point:
      '9933e1f89e8a3c4d7fdcccdbd518089e2bd4d8180a261f18d9c247a52768ebce98dc7328a39814a8f911086a1dd50cbe015e2a53b7bf78b55288893daa15c346640e8831d72a12bdedd979d28470c34823b8d1c3f4795d9c3984a247132e94fe',
  spkiDer:
      '308182301d060d2b0601040182dc7c0503010201060c2b0601040182dc7c05030201036100'
      '9933e1f89e8a3c4d7fdcccdbd518089e2bd4d8180a261f18d9c247a52768ebce98dc7328a39814a8f911086a1dd50cbe015e2a53b7bf78b55288893daa15c346640e8831d72a12bdedd979d28470c34823b8d1c3f4795d9c3984a247132e94fe',
);

// A small helper: compares two byte buffers via hex, so a failed `expect`
// prints a readable hex diff instead of a wall of raw integers.
Matcher equalsBytes(List<int> expected) => predicate<List<int>>(
  (actual) =>
      BytesUtils.toHexString(actual) == BytesUtils.toHexString(expected),
  'equals bytes ${BytesUtils.toHexString(expected)}',
);

void derTest() {
  group('hex / PEM helpers', () {
    test('derToPem / pemToDer round-trip a real SPKI blob', () {
      final der = BytesUtils.fromHexString(secp256k1Vectors[0].spkiDer);
      final pem = DerUtils.derToPem(der, 'PUBLIC KEY');
      expect(pem, startsWith('-----BEGIN PUBLIC KEY-----\n'));
      expect(pem.trim(), endsWith('-----END PUBLIC KEY-----'));
      expect(DerUtils.pemToDer(pem), equalsBytes(der));
    });
  });

  group('List<int> safety', () {
    test('a plain List<int> encodes identically to a Uint8List', () {
      final plainSeed = List<int>.generate(32, (i) => i); // NOT a Uint8List
      final fromPlainList = DerCodec.encodeEd25519PrivateKeyPkcs8(plainSeed);
      final fromUint8List = DerCodec.encodeEd25519PrivateKeyPkcs8(plainSeed);
      expect(fromPlainList, equalsBytes(fromUint8List));
    });

    test(
      'an out-of-range List<int> passed into a real encoder surfaces the same error',
      () {
        expect(
          () => DerCodec.encodeEd25519PublicKeySpki(
            List<int>.generate(32, (i) => i == 0 ? 300 : 1),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );
  });

  group('secp256k1', () {
    test('generator point (private key = 1): SEC1 round-trip', () {
      final priv = BytesUtils.fromHexString(generatorVector.privateKey);
      final pubUncompressed = BytesUtils.fromHexString(
        generatorVector.publicKeyUncompressed,
      );
      final sec1 = DerCodec.encodeSecp256k1PrivateKeySec1(
        priv,
        publicKeyPoint: pubUncompressed,
      );
      final decoded = DerCodec.decodeSecp256k1PrivateKeySec1(sec1);
      expect(decoded.privateKey, equalsBytes(priv));
      expect(decoded.publicKeyPoint, equalsBytes(pubUncompressed));
      expect(decoded.curveOid, equals(Oids.secp256k1));
    });

    for (var i = 0; i < secp256k1Vectors.length; i++) {
      final v = secp256k1Vectors[i];
      final priv = BytesUtils.fromHexString(v.privateKey);
      final pubUncompressed = BytesUtils.fromHexString(v.publicKeyUncompressed);
      final pubCompressed = BytesUtils.fromHexString(v.publicKeyCompressed);

      group('vector[$i]', () {
        test('SEC1 encode matches OpenSSL output byte-for-byte', () {
          final sec1 = DerCodec.encodeSecp256k1PrivateKeySec1(
            priv,
            publicKeyPoint: pubUncompressed,
          );
          expect(sec1, equalsBytes(BytesUtils.fromHexString(v.sec1Der)));
        });

        test('SEC1 round-trips through our own encoder', () {
          final sec1 = DerCodec.encodeSecp256k1PrivateKeySec1(
            priv,
            publicKeyPoint: pubUncompressed,
          );
          final decoded = DerCodec.decodeSecp256k1PrivateKeySec1(sec1);
          expect(decoded.privateKey, equalsBytes(priv));
          expect(decoded.publicKeyPoint, equalsBytes(pubUncompressed));
        });

        test('SEC1 decodes OpenSSL-produced bytes directly', () {
          final decoded = DerCodec.decodeSecp256k1PrivateKeySec1(
            BytesUtils.fromHexString(v.sec1Der),
          );
          expect(decoded.privateKey, equalsBytes(priv));
        });

        test('PKCS8 encode matches OpenSSL output byte-for-byte', () {
          final pkcs8 = DerCodec.encodeSecp256k1PrivateKeyPkcs8(
            priv,
            publicKeyPoint: pubUncompressed,
          );
          expect(pkcs8, equalsBytes(BytesUtils.fromHexString(v.pkcs8Der)));
          final key = Secp256k1PrivateKey.fromBytes(priv);
          final keyDer = key.toDer(pubKeyMode: CryptoKeyEncoding.uncompressed);
          expect(keyDer, BytesUtils.fromHexString(v.pkcs8Der));
          final keyDecode = Secp256k1PrivateKey.fromDer(keyDer);
          expect(key, keyDecode);
        });

        test('PKCS8 round-trips through our own encoder', () {
          final pkcs8 = DerCodec.encodeSecp256k1PrivateKeyPkcs8(
            priv,
            publicKeyPoint: pubUncompressed,
          );
          expect(
            DerCodec.decodeSecp256k1PrivateKeyPkcs8(pkcs8).privateKey,
            equalsBytes(priv),
          );
        });

        test('PKCS8 decodes OpenSSL-produced bytes directly', () {
          final decoded = DerCodec.decodeSecp256k1PrivateKeyPkcs8(
            BytesUtils.fromHexString(v.pkcs8Der),
          );
          expect(decoded.privateKey, equalsBytes(priv));
        });

        test('SPKI (uncompressed point) matches OpenSSL and round-trips', () {
          final spki = DerCodec.encodeSecp256k1PublicKeySpki(pubUncompressed);
          expect(spki, equalsBytes(BytesUtils.fromHexString(v.spkiDer)));
          expect(
            DerCodec.decodeSecp256k1PublicKeySpki(spki),
            equalsBytes(pubUncompressed),
          );
          expect(
            DerCodec.decodeSecp256k1PublicKeySpki(
              BytesUtils.fromHexString(v.spkiDer),
            ),
            equalsBytes(pubUncompressed),
          );
          final key = Secp256k1PublicKey.fromBytes(pubUncompressed);
          final keyDer = key.toDer(pubKeyMode: CryptoKeyEncoding.uncompressed);
          expect(keyDer, BytesUtils.fromHexString(v.spkiDer));
          final keyDecode = Secp256k1PublicKey.fromDer(keyDer);
          expect(key, keyDecode);
        });

        test('SPKI round-trips with a compressed point payload', () {
          final spki = DerCodec.encodeSecp256k1PublicKeySpki(pubCompressed);
          expect(
            DerCodec.decodeSecp256k1PublicKeySpki(spki),
            equalsBytes(pubCompressed),
          );
        });

        test('SEC1 with the optional public key field omitted', () {
          final sec1 = DerCodec.encodeSecp256k1PrivateKeySec1(priv);
          final decoded = DerCodec.decodeSecp256k1PrivateKeySec1(sec1);
          expect(decoded.publicKeyPoint, isNull);
          expect(decoded.privateKey, equalsBytes(priv));
        });
      });
    }

    test('encode rejects a wrong-length private key', () {
      expect(
        () => DerCodec.encodeSecp256k1PrivateKeySec1(
          BytesUtils.fromHexString('aabbcc'),
        ),
        throwsA(isA<BuError>()),
      );
    });

    test(
      'decodeSecp256k1PrivateKeyPkcs8 rejects an Ed25519 blob (wrong algorithm OID)',
      () {
        expect(
          () => DerCodec.decodeSecp256k1PrivateKeyPkcs8(
            BytesUtils.fromHexString(ed25519Vectors[0].pkcs8Der),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );

    test(
      'decodeSecp256k1PublicKeySpki rejects an Ed25519 blob (wrong algorithm OID)',
      () {
        expect(
          () => DerCodec.decodeSecp256k1PublicKeySpki(
            BytesUtils.fromHexString(ed25519Vectors[0].spkiDer),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );

    test(
      'decodeSecp256k1PrivateKeySec1 rejects a truncated/malformed SEQUENCE',
      () {
        expect(
          () => DerCodec.decodeSecp256k1PrivateKeySec1(
            BytesUtils.fromHexString('3003020101'),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );

    test(
      'DerReader rejects a length byte claiming more data than is present',
      () {
        expect(
          () => DerReader(BytesUtils.fromHexString('3005')).readNode(),
          throwsA(isA<BuError>()),
        );
      },
    );
  });

  group('secp256r1 (NIST P-256 / Nist256p1)', () {
    test('generator point (private key = 1): SEC1 round-trip', () {
      final priv = BytesUtils.fromHexString(
        secp256r1GeneratorVector.privateKey,
      );
      final pubUncompressed = BytesUtils.fromHexString(
        secp256r1GeneratorVector.publicKeyUncompressed,
      );
      final sec1 = DerCodec.encodeSecp256r1PrivateKeySec1(
        priv,
        publicKeyPoint: pubUncompressed,
      );
      final decoded = DerCodec.decodeSecp256r1PrivateKeySec1(sec1);
      expect(decoded.privateKey, equalsBytes(priv));
      expect(decoded.publicKeyPoint, equalsBytes(pubUncompressed));
      expect(decoded.curveOid, equals(Oids.secp256r1));
    });

    for (var i = 0; i < secp256r1Vectors.length; i++) {
      final v = secp256r1Vectors[i];
      final priv = BytesUtils.fromHexString(v.privateKey);
      final pubUncompressed = BytesUtils.fromHexString(v.publicKeyUncompressed);
      final pubCompressed = BytesUtils.fromHexString(v.publicKeyCompressed);

      group('vector[$i]', () {
        test("key", () {
          final key = Secp256r1PrivateKey.fromDer(
            BytesUtils.fromHexString(v.pkcs8Der),
          );
          expect(
            key.publicKey.toBytes(mode: CryptoKeyEncoding.base),
            pubCompressed,
          );
          expect(
            key.publicKey.toBytes(mode: CryptoKeyEncoding.uncompressed),
            pubUncompressed,
          );
          expect(
            key.toDer(pubKeyMode: CryptoKeyEncoding.uncompressed),
            BytesUtils.fromHexString(v.pkcs8Der),
          );
          expect(
            key.publicKey.toDer(pubKeyMode: CryptoKeyEncoding.uncompressed),
            BytesUtils.fromHexString(v.spkiDer),
          );
        });
        test('SEC1 encode matches OpenSSL output byte-for-byte', () {
          final sec1 = DerCodec.encodeSecp256r1PrivateKeySec1(
            priv,
            publicKeyPoint: pubUncompressed,
          );
          expect(sec1, equalsBytes(BytesUtils.fromHexString(v.sec1Der)));
        });

        test('SEC1 round-trips through our own encoder', () {
          final sec1 = DerCodec.encodeSecp256r1PrivateKeySec1(
            priv,
            publicKeyPoint: pubUncompressed,
          );
          final decoded = DerCodec.decodeSecp256r1PrivateKeySec1(sec1);
          expect(decoded.privateKey, equalsBytes(priv));
          expect(decoded.publicKeyPoint, equalsBytes(pubUncompressed));
        });

        test('SEC1 decodes OpenSSL-produced bytes directly', () {
          final decoded = DerCodec.decodeSecp256r1PrivateKeySec1(
            BytesUtils.fromHexString(v.sec1Der),
          );
          expect(decoded.privateKey, equalsBytes(priv));
        });

        test('PKCS8 encode matches OpenSSL output byte-for-byte', () {
          final pkcs8 = DerCodec.encodeSecp256r1PrivateKeyPkcs8(
            priv,
            publicKeyPoint: pubUncompressed,
          );
          expect(pkcs8, equalsBytes(BytesUtils.fromHexString(v.pkcs8Der)));
        });

        test('PKCS8 round-trips through our own encoder', () {
          final pkcs8 = DerCodec.encodeSecp256r1PrivateKeyPkcs8(
            priv,
            publicKeyPoint: pubUncompressed,
          );
          expect(
            DerCodec.decodeSecp256r1PrivateKeyPkcs8(pkcs8).privateKey,
            equalsBytes(priv),
          );
        });

        test('PKCS8 decodes OpenSSL-produced bytes directly', () {
          final decoded = DerCodec.decodeSecp256r1PrivateKeyPkcs8(
            BytesUtils.fromHexString(v.pkcs8Der),
          );
          expect(decoded.privateKey, equalsBytes(priv));
        });

        test('SPKI (uncompressed point) matches OpenSSL and round-trips', () {
          final spki = DerCodec.encodeSecp256r1PublicKeySpki(pubUncompressed);
          expect(spki, equalsBytes(BytesUtils.fromHexString(v.spkiDer)));
          expect(
            DerCodec.decodeSecp256r1PublicKeySpki(spki),
            equalsBytes(pubUncompressed),
          );
          expect(
            DerCodec.decodeSecp256r1PublicKeySpki(
              BytesUtils.fromHexString(v.spkiDer),
            ),
            equalsBytes(pubUncompressed),
          );
        });

        test('SPKI round-trips with a compressed point payload', () {
          final spki = DerCodec.encodeSecp256r1PublicKeySpki(pubCompressed);
          expect(
            DerCodec.decodeSecp256r1PublicKeySpki(spki),
            equalsBytes(pubCompressed),
          );
        });

        test('SEC1 with the optional public key field omitted', () {
          final sec1 = DerCodec.encodeSecp256r1PrivateKeySec1(priv);
          final decoded = DerCodec.decodeSecp256r1PrivateKeySec1(sec1);
          expect(decoded.publicKeyPoint, isNull);
          expect(decoded.privateKey, equalsBytes(priv));
        });

        test('PEM round-trips for both PKCS8 and SPKI', () {
          final pkcs8 = DerCodec.encodeSecp256r1PrivateKeyPkcs8(
            priv,
            publicKeyPoint: pubUncompressed,
          );
          final spki = DerCodec.encodeSecp256r1PublicKeySpki(pubUncompressed);
          expect(
            DerUtils.pemToDer(DerUtils.derToPem(pkcs8, 'PRIVATE KEY')),
            equalsBytes(pkcs8),
          );
          expect(
            DerUtils.pemToDer(DerUtils.derToPem(spki, 'PUBLIC KEY')),
            equalsBytes(spki),
          );
        });
      });
    }

    test('encode rejects a wrong-length private key', () {
      expect(
        () => DerCodec.encodeSecp256r1PrivateKeySec1(
          BytesUtils.fromHexString('aabbcc'),
        ),
        throwsA(isA<BuError>()),
      );
    });

    test(
      'decodeSecp256r1PrivateKeyPkcs8 rejects an Ed25519 blob (wrong algorithm OID)',
      () {
        expect(
          () => DerCodec.decodeSecp256r1PrivateKeyPkcs8(
            BytesUtils.fromHexString(ed25519Vectors[0].pkcs8Der),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );

    test(
      'decodeSecp256r1PrivateKeyPkcs8 rejects a secp256k1 blob (right ecPublicKey OID, wrong curve OID)',
      () {
        expect(
          () => DerCodec.decodeSecp256r1PrivateKeyPkcs8(
            BytesUtils.fromHexString(secp256k1Vectors[0].pkcs8Der),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );

    test(
      'decodeSecp256r1PublicKeySpki rejects an Ed25519 blob (wrong algorithm OID)',
      () {
        expect(
          () => DerCodec.decodeSecp256r1PublicKeySpki(
            BytesUtils.fromHexString(ed25519Vectors[0].spkiDer),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );

    test(
      'decodeSecp256r1PublicKeySpki rejects a secp256k1 blob (right ecPublicKey OID, wrong curve OID)',
      () {
        expect(
          () => DerCodec.decodeSecp256r1PublicKeySpki(
            BytesUtils.fromHexString(secp256k1Vectors[0].spkiDer),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );

    test(
      'decodeSecp256r1PrivateKeySec1 rejects a truncated/malformed SEQUENCE',
      () {
        expect(
          () => DerCodec.decodeSecp256r1PrivateKeySec1(
            BytesUtils.fromHexString('3003020101'),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );

    test(
      'secp256k1 vs secp256r1 SEC1 blobs are not cross-decodable as the same curve',
      () {
        // Same wrapper shape, but the k1 vector's curve OID differs; make sure
        // decode does not silently accept the wrong curve's SEC1 bytes.
        final decoded = DerCodec.decodeSecp256r1PrivateKeySec1(
          BytesUtils.fromHexString(secp256k1Vectors[0].sec1Der),
        );
        expect(decoded.curveOid, isNot(equals(Oids.secp256r1)));
        expect(decoded.curveOid, equals(Oids.secp256k1));
      },
    );
  });

  group('Ed25519', () {
    test('RFC 8032 Test 1: PKCS8 round-trip', () {
      final seed = BytesUtils.fromHexString(rfc8032Test1.seed);
      final pkcs8 = DerCodec.encodeEd25519PrivateKeyPkcs8(seed);
      expect(DerCodec.decodeEd25519PrivateKeyPkcs8(pkcs8), equalsBytes(seed));
    });

    test('RFC 8032 Test 1: SPKI round-trip', () {
      final pub = BytesUtils.fromHexString(rfc8032Test1.publicKey);
      final spki = DerCodec.encodeEd25519PublicKeySpki(pub);
      expect(DerCodec.decodeEd25519PublicKeySpki(spki), equalsBytes(pub));
    });

    for (var i = 0; i < ed25519Vectors.length; i++) {
      final v = ed25519Vectors[i];
      final seed = BytesUtils.fromHexString(v.seed);
      final pub = BytesUtils.fromHexString(v.publicKey);

      group('vector[$i]', () {
        test('PKCS8 matches OpenSSL and round-trips', () {
          final pkcs8 = DerCodec.encodeEd25519PrivateKeyPkcs8(seed);
          expect(pkcs8, equalsBytes(BytesUtils.fromHexString(v.pkcs8Der)));
          expect(
            DerCodec.decodeEd25519PrivateKeyPkcs8(pkcs8),
            equalsBytes(seed),
          );
          expect(
            DerCodec.decodeEd25519PrivateKeyPkcs8(
              BytesUtils.fromHexString(v.pkcs8Der),
            ),
            equalsBytes(seed),
          );
          final key = ED25519PrivateKey.fromBytes(seed);
          final derBytes = key.toDer();
          expect(key.toDer(), BytesUtils.fromHexString(v.pkcs8Der));
          final decodeKye = ED25519PrivateKey.fromDer(derBytes);
          expect(key, decodeKye);
        });

        test('SPKI matches OpenSSL and round-trips', () {
          final spki = DerCodec.encodeEd25519PublicKeySpki(pub);
          expect(spki, equalsBytes(BytesUtils.fromHexString(v.spkiDer)));
          expect(DerCodec.decodeEd25519PublicKeySpki(spki), equalsBytes(pub));
          expect(
            DerCodec.decodeEd25519PublicKeySpki(
              BytesUtils.fromHexString(v.spkiDer),
            ),
            equalsBytes(pub),
          );
          final key = ED25519PublicKey.fromBytes(pub);
          final derBytes = key.toDer();
          expect(key.toDer(), BytesUtils.fromHexString(v.spkiDer));
          final decodeKye = ED25519PublicKey.fromDer(derBytes);
          expect(key, decodeKye);
        });

        test('PEM round-trips for both PKCS8 and SPKI', () {
          final pkcs8 = DerCodec.encodeEd25519PrivateKeyPkcs8(seed);
          final spki = DerCodec.encodeEd25519PublicKeySpki(pub);
          expect(
            DerUtils.pemToDer(DerUtils.derToPem(pkcs8, 'PRIVATE KEY')),
            equalsBytes(pkcs8),
          );
          expect(
            DerUtils.pemToDer(DerUtils.derToPem(spki, 'PUBLIC KEY')),
            equalsBytes(spki),
          );
        });
      });
    }

    test('encodeEd25519PrivateKeyPkcs8 rejects a wrong-length seed', () {
      expect(
        () => DerCodec.encodeEd25519PrivateKeyPkcs8(
          BytesUtils.fromHexString('aabb'),
        ),
        throwsA(isA<BuError>()),
      );
    });

    test('encodeEd25519PublicKeySpki rejects a wrong-length public key', () {
      expect(
        () => DerCodec.encodeEd25519PublicKeySpki(
          BytesUtils.fromHexString('aabb'),
        ),
        throwsA(isA<BuError>()),
      );
    });

    test(
      'decodeEd25519PrivateKeyPkcs8 rejects a secp256k1 blob (wrong algorithm OID)',
      () {
        expect(
          () => DerCodec.decodeEd25519PrivateKeyPkcs8(
            BytesUtils.fromHexString(secp256k1Vectors[0].pkcs8Der),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );

    test(
      'decodeEd25519PublicKeySpki rejects a secp256k1 blob (wrong algorithm OID)',
      () {
        expect(
          () => DerCodec.decodeEd25519PublicKeySpki(
            BytesUtils.fromHexString(secp256k1Vectors[0].spkiDer),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );

    test(
      'decodeEd25519PublicKeySpki rejects a public key that is not 32 bytes',
      () {
        expect(
          () => DerCodec.decodeEd25519PublicKeySpki(
            BytesUtils.fromHexString('302a300506032b6570032100aabb'),
          ),
          throwsA(isA<BuError>()),
        );
      },
    );
  });

  group('BLS12-381 (IC G2 public key)', () {
    test('real subnet public key: SPKI matches the byte-for-byte DER wrapper '
        'DFINITY ships and round-trips', () {
      final point = BytesUtils.fromHexString(realSubnetKeyVector.point);
      final spki = DerCodec.encodeBls12381PublicKeySpki(point);
      final k = Bls12G2PublicKey.fromDer(
        BytesUtils.fromHexString(realSubnetKeyVector.spkiDer),
      );
      expect(
        BytesUtils.toHexString(k.toDer(mode: CryptoKeyEncoding.base)),
        realSubnetKeyVector.spkiDer,
      );
      expect(
        spki,
        equalsBytes(BytesUtils.fromHexString(realSubnetKeyVector.spkiDer)),
      );
      expect(DerCodec.decodeBls12381PublicKeySpki(spki), equalsBytes(point));
      expect(
        DerCodec.decodeBls12381PublicKeySpki(
          BytesUtils.fromHexString(realSubnetKeyVector.spkiDer),
        ),
        equalsBytes(point),
      );
    });

    test('SPKI decode rejects an Ed25519 blob (wrong algorithm OID)', () {
      expect(
        () => DerCodec.decodeBls12381PublicKeySpki(
          BytesUtils.fromHexString(ed25519Vectors[0].spkiDer),
        ),
        throwsA(isA<BuError>()),
      );
    });

    test('SPKI decode rejects a secp256k1 blob (wrong algorithm OID)', () {
      expect(
        () => DerCodec.decodeBls12381PublicKeySpki(
          BytesUtils.fromHexString(secp256k1Vectors[0].spkiDer),
        ),
        throwsA(isA<BuError>()),
      );
    });

    test('SPKI decode rejects a truncated/malformed SEQUENCE', () {
      expect(
        () => DerCodec.decodeBls12381PublicKeySpki(
          BytesUtils.fromHexString('3003020101'),
        ),
        throwsA(isA<BuError>()),
      );
    });

    test('raw private key codec validates length and passes bytes through', () {
      final priv = List<int>.generate(32, (i) => i);
      final encoded = DerCodec.encodeBls12381PrivateKeyRaw(priv);
      expect(DerCodec.decodeBls12381PrivateKeyRaw(encoded), equalsBytes(priv));
    });

    test('raw private key codec rejects a wrong-length scalar', () {
      expect(
        () => DerCodec.encodeBls12381PrivateKeyRaw(
          BytesUtils.fromHexString('aabbcc'),
        ),
        throwsA(isA<BuError>()),
      );
    });

    test('Pkcs8 wrapper (our own construction, not a DFINITY/external format) '
        'round-trips', () {
      final priv = List<int>.generate(32, (i) => 31 - i);
      final pkcs8 = DerCodec.encodeBls12381PrivateKeyPkcs8(priv);
      expect(DerCodec.decodeBls12381PrivateKeyPkcs8(pkcs8), equalsBytes(priv));
    });

    test('Pkcs8 decode rejects an Ed25519 blob (wrong algorithm OID)', () {
      expect(
        () => DerCodec.decodeBls12381PrivateKeyPkcs8(
          BytesUtils.fromHexString(ed25519Vectors[0].pkcs8Der),
        ),
        throwsA(isA<BuError>()),
      );
    });
  });
}

void main() {
  BlockchainUtilsTestApi.runTest(derTest, "Der");
}
